CREATE TABLE pemasukan(
   id_pemasukan INTEGER NOT NULL PRIMARY KEY 
  ,id_user      INTEGER NOT NULL
  ,sumber       VARCHAR(18) NOT NULL
  ,jumlah       NUMERIC(12,0) NOT NULL
  ,tanggal      DATE  NOT NULL
);

CREATE TABLE pengeluaran(
   id_pengeluaran INTEGER  NOT NULL PRIMARY KEY 
  ,id_user        INTEGER  NOT NULL
  ,kategori       VARCHAR(19) NOT NULL
  ,jumlah         NUMERIC(12,0)  NOT NULL
  ,tanggal        DATE  NOT NULL
);

-- Buat sequence
CREATE SEQUENCE pemasukan_id_seq START 1;
CREATE SEQUENCE pengeluaran_id_seq START 1;

-- Set kolom id untuk gunakan sequence ini
ALTER TABLE pemasukan ALTER COLUMN id_pemasukan SET DEFAULT nextval('pemasukan_id_seq');
ALTER TABLE pengeluaran ALTER COLUMN id_pengeluaran SET DEFAULT nextval('pengeluaran_id_seq');

-- Sinkronkan sequence dengan ID terbesar yang ada
SELECT setval('pemasukan_id_seq', (SELECT MAX(id_pemasukan) FROM pemasukan));
SELECT setval('pengeluaran_id_seq', (SELECT MAX(id_pengeluaran) FROM pengeluaran));